<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use Nimbly\Capsule\Response;
use Civi\Lughauth\Features\OAuth\Device\Infrastructure\Driver\Rest\DeviceAuthorizationController;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Rest\TokenController;

class DeviceEndpointTest extends OidcIntegrationTestCase
{
    private DeviceAuthorizationController $controller;
    private TokenController $tokenController;

    protected function setUp(): void
    {
        parent::setUp();
        // Register a device-flow capable client alongside the defaults
        $this->clientStore->register(self::CLIENT_ID, self::CLIENT_SECRET, new \Civi\Lughauth\Features\OAuth\Client\Domain\ClientData(
            id: self::CLIENT_ID,
            grants: [
                'client_credentials',
                'authorization_code',
                'refresh_token',
                'urn:ietf:params:oauth:grant-type:device_code',
            ],
            secretLogin: true,
        ));
        $this->controller = $this->container->get(DeviceAuthorizationController::class);
        $this->tokenController = $this->container->get(TokenController::class);
    }

    private function requestDevice(array $extra = []): \Psr\Http\Message\ResponseInterface
    {
        $params = array_merge([
            'client_id' => self::CLIENT_ID,
            'scope' => 'openid profile',
        ], $extra);
        $request = $this->makeRequest('POST', '/oauth/openid/' . self::TENANT . '/device', $params);
        return $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);
    }

    public function testDeviceAuthorizationReturnsRequiredFields(): void
    {
        $response = $this->requestDevice();

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertArrayHasKey('device_code', $body);
        $this->assertArrayHasKey('user_code', $body);
        $this->assertArrayHasKey('verification_uri', $body);
        $this->assertArrayHasKey('verification_uri_complete', $body);
        $this->assertArrayHasKey('expires_in', $body);
        $this->assertArrayHasKey('interval', $body);
    }

    public function testDeviceCodeIsStoredInGateway(): void
    {
        $response = $this->requestDevice();
        $body = $this->decodeJson($response);

        $deviceGateway = $this->container->get(\Civi\Lughauth\Features\OAuth\Device\Domain\Gateway\DeviceAuthorizationGateway::class);
        $stored = $deviceGateway->findByDeviceCode($body['device_code']);

        $this->assertNotNull($stored);
        $this->assertSame(self::TENANT, $stored->tenant);
        $this->assertSame(self::CLIENT_ID, $stored->clientId);
    }

    public function testVerificationUriContainsTenant(): void
    {
        $response = $this->requestDevice();
        $body = $this->decodeJson($response);

        $this->assertStringContainsString(self::TENANT, $body['verification_uri']);
    }

    public function testVerificationUriCompleteContainsUserCode(): void
    {
        $response = $this->requestDevice();
        $body = $this->decodeJson($response);

        $this->assertStringContainsString(urlencode($body['user_code']), $body['verification_uri_complete']);
    }

    public function testScopeIsReturnedWhenProvided(): void
    {
        $response = $this->requestDevice(['scope' => 'openid api:read']);
        $body = $this->decodeJson($response);

        $this->assertArrayHasKey('scope', $body);
        $this->assertSame('openid api:read', $body['scope']);
    }

    public function testScopeIsOmittedWhenEmpty(): void
    {
        $response = $this->requestDevice(['scope' => '']);
        $body = $this->decodeJson($response);

        $this->assertArrayNotHasKey('scope', $body);
    }

    public function testUnknownClientReturns401(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/' . self::TENANT . '/device', [
            'client_id' => 'unknown-client',
        ]);
        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(401, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('invalid_client', $body['error']);
    }

    public function testMissingClientIdReturns400(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/' . self::TENANT . '/device', []);
        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('invalid_request', $body['error']);
    }

    public function testClientNotGrantedDeviceFlowReturns401(): void
    {
        $this->clientStore->register('code-only-client', 'secret', new \Civi\Lughauth\Features\OAuth\Client\Domain\ClientData(
            id: 'code-only-client',
            grants: ['authorization_code'],
            secretLogin: false,
        ));

        $request = $this->makeRequest('POST', '/oauth/openid/' . self::TENANT . '/device', [
            'client_id' => 'code-only-client',
        ]);
        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(401, $response->getStatusCode());
    }

    public function testEachRequestProducesUniqueDeviceAndUserCodes(): void
    {
        $codes = [];
        for ($i = 0; $i < 3; $i++) {
            $body = $this->decodeJson($this->requestDevice());
            $codes[] = $body['device_code'];
        }
        $this->assertSame(count($codes), count(array_unique($codes)));
    }

    public function testDevicePollPendingReturnsAuthorizationPending(): void
    {
        $deviceBody = $this->decodeJson($this->requestDevice());
        $deviceCode = $deviceBody['device_code'];

        $response = $this->tokenController->post(
            $this->makeRequest('POST', '/oauth/openid/' . self::TENANT . '/token', [
                'grant_type' => 'urn:ietf:params:oauth:grant-type:device_code',
                'device_code' => $deviceCode,
                'client_id' => self::CLIENT_ID,
            ]),
            new Response(200),
            ['tenant' => self::TENANT]
        );

        $this->assertSame(400, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('authorization_pending', $body['error']);
    }

    public function testDevicePollAfterApprovalReturnsTokens(): void
    {
        $deviceBody = $this->decodeJson($this->requestDevice());
        $deviceCode = $deviceBody['device_code'];

        $deviceGateway = $this->container->get(\Civi\Lughauth\Features\OAuth\Device\Domain\Gateway\DeviceAuthorizationGateway::class);
        $deviceGateway->approve($deviceCode, new \Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult(
            valid: true,
            id: self::USER_ID,
            tenant: self::TENANT,
            scope: 'openid profile',
        ));

        $response = $this->tokenController->post(
            $this->makeRequest('POST', '/oauth/openid/' . self::TENANT . '/token', [
                'grant_type' => 'urn:ietf:params:oauth:grant-type:device_code',
                'device_code' => $deviceCode,
                'client_id' => self::CLIENT_ID,
            ]),
            new Response(200),
            ['tenant' => self::TENANT]
        );

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertArrayHasKey('access_token', $body);
        $this->assertSame('Bearer', $body['token_type']);
    }
}
